module.exports = {
    onAction: function(transport, actionId, params) {
        var userToken = engine.secret("api_key") || params.api_key || "";
        var lightId = params.light_id || "1";

        if (actionId === "hue_get_light_state" || actionId === "get_light_state" || actionId === "get_light") {
            var uri = "/api/" + userToken + "/lights/" + lightId;
            return engine.http.get(uri).then(function(res) {
                if (res.json && res.json.state) {
                    engine.setVariable("hue_light_" + lightId + "_on", res.json.state.on ? "true" : "false");
                    if (res.json.state.bri !== undefined) engine.setVariable("hue_light_" + lightId + "_bri", String(res.json.state.bri));
                }
                return "Queried Light " + lightId + " State";
            });
        }
        if (actionId === "hue_toggle_light" || actionId === "toggle_light") {
            var uri = "/api/" + userToken + "/lights/" + lightId + "/state";
            var body = { on: params.state === "on" || params.state === "true" };
            return engine.http.post(uri, body).then(function(res) {
                engine.setVariable("hue_light_" + lightId + "_on", body.on ? "true" : "false");
                return "Light " + lightId + (body.on ? " Turned On" : " Turned Off");
            });
        }
        if (actionId === "hue_set_brightness" || actionId === "brightness") {
            var bri = parseInt(params.brightness || "254", 10);
            var uri = "/api/" + userToken + "/lights/" + lightId + "/state";
            return engine.http.post(uri, { bri: bri }).then(function(res) {
                engine.setVariable("hue_light_" + lightId + "_bri", String(bri));
                return "Set Light " + lightId + " Brightness to " + bri;
            });
        }
        return "Hue Action Sent";
    }
};
